  const mermaidNodeId=id=>'n_'+id.replace(/[^a-zA-Z0-9_]/g,'_');
  function mermaidSource(module){const selected=graphNodes.filter(n=>module==='whole'||n.module===module),ids=new Set(selected.map(n=>n.id));const lines=['flowchart LR'];for(const group of ['web','service','contracts']){const members=selected.filter(n=>n.module===group);if(!members.length)continue;lines.push(`subgraph g_${group}["${moduleLabels[group]}"]`);for(const node of members)lines.push(`  ${mermaidNodeId(node.id)}["${node.label}"]`);lines.push('end');}for(const edge of graphLinks)if(ids.has(edge.source)&&ids.has(edge.target))lines.push(`${mermaidNodeId(edge.source)} --> ${mermaidNodeId(edge.target)}`);return lines.join('\n');}
