  function saveField(el){if(!el.dataset.taskField)return;const d=draft();if(el.multiple)d[el.name]=Array.from(el.selectedOptions).map(o=>o.value);else d[el.name]=el.type==='checkbox'?el.checked:el.value;ui.taskPreview=false;if(el.name==='files[0].relativePath'){d['fileContexts[0].relativePath']=el.value;const bound=document.querySelector('[name="fileContexts[0].relativePath"]');if(bound)bound.value=el.value;}if(el.name==='type'){const parent=document.querySelector('[name=parentId]');if(parent){parent.disabled=el.value==='epic';if(parent.disabled){parent.value='';d.parentId='';}}}if(el.name==='noRisks'){d.risks=el.checked?'none':'';const risk=document.querySelector('[name="risks"]');if(risk)risk.value=d.risks;}if(el.name.includes('Operation')){const rename=d['files[0].plannedOperation']==='rename'||d['files[0].actualOperation']==='rename';document.querySelectorAll('[data-rename-field]').forEach(element=>element.hidden=!rename);}}
